steps.script:
var wbm = GameState.state.units["U_WARBOSS_B"].models[0]
var u = GameState.state.units["U_WITCHSEEKERS_C"]
var i = 0
for m in u.models:
	m.position = {"x": float(wbm.position.x) - 500.0, "y": float(wbm.position.y) + i * 30.0}
	i += 1
var best = 9999.0
for m in u.models:
	var d1 = Measurement.model_to_model_distance_inches(m, wbm)
	if d1 < best:
		best = d1
var shift = Measurement.inches_to_px(best - 4.0)
for m in u.models:
	m.position = {"x": float(m.position.x) + shift, "y": float(m.position.y)}
best = 9999.0
for m in u.models:
	var d2 = Measurement.model_to_model_distance_inches(m, wbm)
	if d2 < best:
		best = d2
return snappedf(best, 0.01)

var ph = PhaseManager.get_current_phase_instance()
var pc = ph.get("heroic_intervention_pending_charge")
return "mode=%s distance=%d rolls=%s" % [str(pc.get("mode")), int(pc.get("distance")), str(pc.get("dice_rolls"))]

var m = tree.root.get_node("Main")
var t = m.charge_controller.dice_log_display.get_parsed_text()
return t.contains("Into the Fray") and t.contains("= 8\"") and t.contains("caps the charge roll at 6\" — 8\" becomes 6\"")

var t = ""
for e in GameEventLog.get_all_entries():
	t += str(e.get("text", e)) + "\n"
return t.contains("Heroic Intervention (Into the Fray): 2D6 = 8 (2 + 6), capped at 6\" — charge succeeded")
